# Enumerate all diagonal line equations, marker groups, and demos behavior.
from collections import defaultdict
examples=[('d1',9,9,{1:[(2,1),(7,6)],6:[]}),('d2',8,11,{1:[(1,6),(6,1)],6:[(3,4)]}),('d3',9,12,{1:[(1,7),(7,1)],6:[(6,7)]}),('d4',15,12,{1:[(3,1),(9,7)],6:[(2,9),(5,3),(8,6),(13,4)]})]
for name,h,w,colors in examples:
  print(name)
  for color,pts in colors.items():
    print(color,'coords',pts)
    # diagonal groups by c-r and c+r
    for key,fn in [('d',lambda p:p[1]-p[0]),('s',lambda p:p[0]+p[1])]:
      groups=defaultdict(list)
      for p in pts:groups[fn(p)].append(p)
      print(key,{k:v for k,v in groups.items() if len(v)>1})

